class ContactInfo {
    private String email;
    private String phone;

    public ContactInfo(String email, String phone) {
        this.email = email;
        this.phone = phone;
    }

    public String getFormatted() {
        return email + " | " + phone;
    }
}

class Address {
    private String city;
    private String country;

    public Address(String city, String country) {
        this.city = city;
        this.country = country;
    }

    public String getLocation() {
        return city + ", " + country;
    }
}

class Student {
    private String name;
    private Address address;         // Nested object 1
    private ContactInfo contactInfo; // Nested object 2

    public Student(String name, Address address, ContactInfo contactInfo) {
        this.name = name;
        this.address = address;
        this.contactInfo = contactInfo;
    }

    public void printDossier() {
        System.out.println("Student: " + name);
        System.out.println("Location: " + address.getLocation());
        System.out.println("Contact:  " + contactInfo.getFormatted());
    }
}

public class NestedDemo {
    public static void main(String[] args) {
        Address addr = new Address("Boston", "USA");
        ContactInfo contact = new ContactInfo("alice@univ.edu", "555-0199");
        Student student = new Student("Alice Smith", addr, contact);
        student.printDossier();
    }
}

