class Dimensions {
    private double length, width, height;
    public Dimensions(double l, double w, double h) {
        this.length = l; this.width = w; this.height = h;
    }
    public double getVolume() { return length * width * height; }
}

class Box {
    private String label;
    private Dimensions dimensions; // Can be null if unknown

    public Box(String label, Dimensions dimensions) {
        this.label = label;
        this.dimensions = dimensions;
    }

    public void printVolumeReport() {
        if (dimensions != null) {
            System.out.println("Box [" + label + "] Volume: " + dimensions.getVolume() + " cm3");
        } else {
            System.out.println("Box [" + label + "] Volume: UNKNOWN (Dimensions unmeasured)");
        }
    }
}

public class NullSafeDemo {
    public static void main(String[] args) {
        Box b1 = new Box("Shipping-A", new Dimensions(10, 20, 30));
        Box b2 = new Box("Shipping-B", null);

        b1.printVolumeReport();
        b2.printVolumeReport();
    }
}

