class GpsCoordinate {
    private double lat, lon;
    public GpsCoordinate(double lat, double lon) {
        this.lat = lat;
        this.lon = lon;
    }
    public String toFormattedString() {
        return "Lat: " + lat + ", Lon: " + lon;
    }
}

class TelemetryUnit {
    private int speedKmh;
    private GpsCoordinate coordinate;
    public TelemetryUnit(int speedKmh, GpsCoordinate coordinate) {
        this.speedKmh = speedKmh;
        this.coordinate = coordinate;
    }
    public void logTelemetry() {
        System.out.println("[Telemetry] Speed: " + speedKmh + " km/h | Position: (" + coordinate.toFormattedString() + ")");
    }
}

class FleetTruck {
    private String truckId;
    private TelemetryUnit telemetry;
    public FleetTruck(String truckId, TelemetryUnit telemetry) {
        this.truckId = truckId;
        this.telemetry = telemetry;
    }
    public void pingServer() {
        System.out.println("[Truck " + truckId + "] Broadcasting packet...");
        telemetry.logTelemetry();
    }
}

public class TelemetryApp {
    public static void main(String[] args) {
        GpsCoordinate gps = new GpsCoordinate(40.7128, -74.0060);
        TelemetryUnit unit = new TelemetryUnit(85, gps);
        FleetTruck truck = new FleetTruck("TRK-900", unit);
        truck.pingServer();
    }
}

class CreditScore {
    private int score;
    public CreditScore(int score) {
        this.score = score;
    }
    public int getScore() {
        return score;
    }
}

class CustomerProfile {
    private String fullName;
    private CreditScore creditScore;
    public CustomerProfile(String fullName, CreditScore creditScore) {
        this.fullName = fullName;
        this.creditScore = creditScore;
    }
    public void printRiskAssessment() {
        if (creditScore == null) {
            System.out.println("Customer [" + fullName + "]: Risk Unknown (No Credit File)");
        } else if (creditScore.getScore() >= 700) {
            System.out.println("Customer [" + fullName + "]: Low Risk (Score: " + creditScore.getScore() + ")");
        } else {
            System.out.println("Customer [" + fullName + "]: High Risk (Score: " + creditScore.getScore() + ")");
        }
    }
}

public class CreditApp {
    public static void main(String[] args) {
        CustomerProfile c1 = new CustomerProfile("Alice", new CreditScore(740));
        CustomerProfile c2 = new CustomerProfile("Bob", new CreditScore(620));
        CustomerProfile c3 = new CustomerProfile("Charlie", null);

        c1.printRiskAssessment();
        c2.printRiskAssessment();
        c3.printRiskAssessment();
    }
}

