        this.total = total;
        this.address = address;
    }

    public void printInvoice() {
        System.out.println("Order: " + orderId + " | Total: $" + total);
        if (address != null) {
            System.out.println("Ship To: " + address.getFormatted());
        } else {
            System.out.println("Ship To: Digital Delivery / Pickup");
        }
    }
}

