        OrderInvoice digitalOrder = new OrderInvoice("ORD-DIGITAL-99", 29.99, null);
        digitalOrder.printInvoice();
    }
}

class AudioPreamp {
    private String brand;
    private double gainDb;
    public AudioPreamp(String brand, double gainDb) {
        this.brand = brand;
        this.gainDb = gainDb;
    }
    public String getPreampSpecs() {
        return brand + " (" + gainDb + "dB gain)";
    }
}

class AudioInterface {
    private String model;
    private int sampleRateKhz;
    private AudioPreamp preamp;
    public AudioInterface(String model, int sampleRateKhz, AudioPreamp preamp) {
        this.model = model;
        this.sampleRateKhz = sampleRateKhz;
        this.preamp = preamp;
    }
    public void describeInterface() {
        System.out.println("[Interface] " + model + " @ " + sampleRateKhz + "kHz with Preamp: " + preamp.getPreampSpecs());
    }
}

class StudioDesk {
    private String studioName;
    private AudioInterface audioInterface;
    public StudioDesk(String studioName, AudioInterface audioInterface) {
        this.studioName = studioName;
        this.audioInterface = audioInterface;
    }
    public void powerUpStudio() {
        System.out.println("=== Studio: " + studioName + " Online ===");
        audioInterface.describeInterface();
    }
}

public class AudioApp {
    public static void main(String[] args) {
        AudioPreamp preamp = new AudioPreamp("Focusrite Scarlett Pre", 56.0);
        AudioInterface iface = new AudioInterface("Clarett+ 2Pre", 192, preamp);
        StudioDesk desk = new StudioDesk("Abbey Sound", iface);
        desk.powerUpStudio();
    }
}
